    "explanation": "データバイアスはデータの収集方法・対象・選択プロセスに起因するため、データ量が多くなっても解消されない場合が多い。むしろ偏ったデータを大量に収集すると、バイアスが増幅されることがある。\n\nA：正しい。サンプリングバイアスの例として、インターネット調査では高齢者・IT非利用者が対象外になりやすい問題がある。\nB：正しい。確証バイアス（Confirmation Bias）は分析者の先入観が結果解釈を歪める認知バイアスであり、データ分析の客観性を損なう。\nC：正しい。生存バイアス（Survivorship Bias）の有名例は「成功した企業のみを分析して成功要因を導く」ケース（失敗企業のデータが欠如）。\n\n【頻出】生存バイアス・サンプリングバイアス・確証バイアスの3種類とその具体例は試験頻出論点。\n【混同注意】「データを増やせばバイアスが消える」という誤解は典型的ひっかけ。偏った収集方法を変えない限り解消しない。"
