    "explanation": "名寄せ（名義統合）とは、同一の人・企業・商品が異なる表記・形式でデータベースに存在する場合に、それらを同一エンティティとして統合・統一する処理のことをいう。「田中太郎」「タナカタロウ」「Tanaka Taro」が同一人物を指す場合、名寄せによって重複を排除し、正確な顧客分析を可能にする。\n\nB：単位の混在（円と千円）はデータの単位統一・スケーリングの問題であり、名寄せではなく単位変換・正規化で対処する。\nC：欠損値の多さは欠損値処理（補完・削除）の問題であり、名寄せとは異なる処理。\nD：バックアップ不足はデータ管理・ガバナンスの問題であり、名寄せとは無関係。\n\n【頻出】名寄せは顧客マスタ管理・CRM・マーケティングデータの統合で頻繁に必要となる実務的なデータクレンジング処理。\n【混同注意】名寄せ（エンティティ統合）とデータクレンジング（品質向上全般）は包含関係。名寄せはクレンジングの一種として位置づけられる。"
