    "answer": 1,
    "explanation": "データカタログとは、組織内に存在するデータ資産のメタデータ（データについてのデータ：所在・定義・オーナー・品質・更新日時等）を一元管理し、データ利用者が必要なデータを検索・発見・理解できるようにするシステムのことをいう。データガバナンスの基盤ツールとして活用される。\n\nA：データの物理的な格納はデータウェアハウスやデータレイクの役割であり、データカタログは「データに関する情報の管理」を行う。\nC：データの暗号化プロトコル（TLS・SSL等）はセキュリティ技術であり、データカタログとは無関係。\nD：学習データセットの自動生成はデータ拡張（Data Augmentation）や合成データ生成ツールの役割であり、データカタログとは異なる。\n\n【頻出】データカタログとメタデータ管理の関係、およびデータガバナンスとの関連はDS検定で出題される。\n【混同注意】データカタログ＝「データの地図」（何がどこにあるかを示す）、データウェアハウス＝「データの倉庫」（データ本体を格納する）という役割の違いを押さえる。"
