    "answer": 1,
    "explanation": "メタデータとは「データについてのデータ」であり、データの属性・特性・文脈を説明する付随情報のことをいう。例として、写真ファイルのメタデータには撮影日時・GPS位置情報・カメラ機種等が含まれる。データベースのメタデータにはテーブル名・カラム名・データ型・更新日時等が含まれる。\n\nA：分析の出力値（予測値・集計値）はメタデータではなく、分析結果データそのものである。\nC：匿名化後のデータは「匿名加工情報」であり、メタデータとは異なる概念。\nD：複数ソースを結合した派生データは「統合データ」や「加工データ」であり、メタデータの定義とは異なる。\n\n【頻出】メタデータの具体例（ファイルサイズ・作成日時・データ型・カラム定義）とデータカタログとの関係は出題される。\n【混同注意】メタデータは「データ本体ではなく、データを説明する情報」という定義を明確に区別する。図書館の蔵書目録（タイトル・著者・ページ数）が本の「メタデータ」に相当するイメージで覚える。"
