    "explanation": "クラスタリングとは、教師なし学習の代表的手法であり、正解ラベルが与えられていないデータに対して、データ間の類似性・距離に基づいて自動的にグループ（クラスタ）を発見する手法のことをいう。代表的アルゴリズムにk-means・階層クラスタリング・DBSCAN等がある。\n\nA：正解ラベルあり訓練データを使う学習は教師あり学習であり、クラスタリングは教師なし学習に分類される。\nB：事前定義されたカテゴリへの分類は「分類（Classification）」であり、教師あり学習の一種。クラスタリングは事前にカテゴリを定義しない。\nD：時系列データの将来予測は時系列分析（ARIMA・LSTMなど）の領域であり、クラスタリングとは異なる目的の手法。\n\n【頻出】クラスタリングの代表手法k-meansの概要（クラスタ数k事前指定・重心への距離で割り当て）と活用例（顧客セグメンテーション）は出題される。\n【混同注意】クラスタリング（教師なし・グループ自動発見）と分類（教師あり・既知カテゴリへの割り当て）の区別は最頻出の誤答ポイント。"
