    "explanation": "交差検証（Cross-Validation）とは、データセットをk個のサブセット（フォールド）に分割し、k−1個を訓練・1個を検証に使う操作をk回繰り返すことで、モデルの汎化性能（未知データへの適合度）を安定的に推定する手法である。代表的なk分割交差検証（k-fold CV）は過学習の検出やハイパーパラメータ選択に用いられる。\n\nA：並列学習による計算速度の向上はバッチ並列化や分散学習の手法であり、交差検証の目的とは異なる。\nC：学習データをすべて訓練に使い別途テストデータで評価する手法は「ホールドアウト法」であり、交差検証とは異なる評価戦略。\nD：不均衡データのクラス比率調整はオーバーサンプリング（SMOTE等）やアンダーサンプリングの手法であり、交差検証の目的ではない。\n\n【頻出】k-fold交差検証の手順（k回の学習・評価の平均で性能推定）と、データが少ない場合に特に有効な点は出題される。\n【混同注意】交差検証はモデル「評価・選択」のための手法。モデルの「学習」自体を高速化するものではない。"
