    "answer": 0,
    "explanation": "転移学習とは、あるタスク（例：大規模画像認識）で学習して得た知識（重み・特徴量抽出能力）を、別の関連タスク（例：医療画像診断）に再利用する手法のことをいう。大量のデータ・計算資源なしに高精度なモデルを構築できる点が利点。ファインチューニング（事前学習済みモデルを少量のタスク固有データで追加学習する）が代表的な活用形態。\n\nB：データをサーバー間で移動するのはデータ転送・ETLのプロセスであり、転移学習の説明として誤り。\nC：複数GPUへの分散学習は「データ並列・モデル並列」の手法であり、転移学習とは別の概念。\nD：モデルの統計的比較・選定は評価・モデル選択の手法であり、転移学習の定義ではない。\n\n【頻出】転移学習の仕組み（事前学習→ファインチューニング）と、少量データでも高精度が得られる理由（大規模データで学習した特徴表現を流用）は出題される。\n【混同注意】ゼロショット学習（タスク固有データなし）・フューショット学習（ごく少量のデータで対応）も転移学習の発展概念として区別して覚える。"
