    "explanation": "感度分析（Sensitivity Analysis）とは、モデルの入力変数・前提仮定・パラメータを一定の範囲で変化させたとき、出力（予測値・意思決定結果等）がどの程度変動するかを定量的に確認する分析手法のことをいう。どの変数がモデルの結果に最も大きな影響を与えるかを特定し、リスク評価・意思決定の堅牢性確認に用いられる。\n\nB：音声・センサー信号の増幅は計測工学・アナログ電子回路の技術であり、データ分析の感度分析とは全く異なる。\nC：ハイパーパラメータ探索はグリッドサーチ・ランダムサーチ・ベイズ最適化等の手法であり、感度分析の定義とは異なる。\nD：アンケートの回答バイアス補正は「社会的望ましさバイアス」への対処であり、感度分析の説明として誤り。\n\n【頻出】感度分析はシナリオ分析（楽観・基本・悲観シナリオ）とセットで経営・財務モデルに応用される場面で出題される。\n【混同注意】感度分析（特定変数の影響度確認）とXAIのSHAP（特徴量の貢献度評価）は類似の目的をもつが、適用場面と手法が異なる。"
