    "answer": 1,
    "explanation": "CRISP-DM（Cross-Industry Standard Process for Data Mining）とは、データマイニング・データ分析プロジェクトを体系的に進めるための業界標準プロセスモデルのことをいう。①ビジネス理解→②データ理解→③データ準備→④モデリング→⑤評価→⑥展開（デプロイ）の6フェーズで構成され、各フェーズは反復的に進められる。\n\nA：クラウドインフラ自動化はInfrastructure as Code（Terraform等）の領域であり、CRISP-DMの説明として誤り。\nC：機械学習モデルのAPI公開・デプロイメントはMLOps・FastAPI・BentoML等のツール・手法に関連する内容であり、CRISP-DMとは別の概念。\nD：データサイエンティストの資格認定はCDSP（Certified Data Science Professional）等の認定機関が行うものであり、CRISP-DMはプロセスモデルであって資格基準ではない。\n\n【頻出】CRISP-DMの6フェーズの順序と、ビジネス理解が最初のフェーズである点は出題される。各フェーズの反復性（モデリング結果を見てデータ準備に戻る等）も理解しておく。\n【混同注意】CRISP-DM（プロセスモデル）とアジャイル開発（ソフトウェア開発手法）・スクラム（プロジェクト管理フレームワーク）は別の概念。データ分析プロジェクトではCRISP-DMとアジャイルを組み合わせる場合もある。"
