    "explanation": "モンテカルロ法とは、乱数を大量に発生させた繰り返しシミュレーションにより、解析的に求めることが難しい数値（確率・積分値・期待値等）を近似的に推定する計算手法のことをいう。例えば円周率πの推定・リスク評価・金融デリバティブ価格計算などに応用される。\n\nB：名称の由来はモナコのモンテカルロカジノだが、賭け事専用の手法ではなく、物理学・工学・金融・AIなど広範な分野で利用される汎用的な数値計算手法。\nC：データを小集団に分けて検定を繰り返す手法はブートストラップ法または交差検証であり、モンテカルロ法の定義ではない。\nD：残差を最小化するパラメータ探索は最小二乗法・勾配降下法等の最適化手法の説明であり、モンテカルロ法とは異なる。\n\n【頻出】モンテカルロ法の「乱数による反復シミュレーション」という本質と、πの推定・リスク解析への応用例は出題される。\n【混同注意】モンテカルロ法（乱数シミュレーション）とブートストラップ法（リサンプリングによる統計推定）は類似する概念として混同されやすい。"
