    "answer": 1,
    "explanation": "多変量解析とは、3変数以上の複数変数を同時に扱い、変数間の相互関係・構造・因果関係等を明らかにする統計手法の総称のことをいう。代表的な手法として重回帰分析・主成分分析・因子分析・判別分析・クラスター分析・共分散構造分析等がある。\n\nA：1変数のみを対象に基本統計量を算出するのは「一変量解析（記述統計）」の説明であり、多変量解析の定義として誤り。\nC：多変量解析には正規分布を仮定する手法もあれば、仮定しないノンパラメトリック手法もある。「すべての手法が正規分布を仮定する」は誤り。\nD：変数を増やしすぎると次元の呪い（高次元空間での距離の意味の希薄化）・過学習・多重共線性等の問題が生じる。「多いほどよい」は誤り。\n\n【頻出】多変量解析の代表的手法（回帰・主成分・クラスター・因子分析）とそれぞれの目的（予測・次元削減・グループ化・潜在変数発見）の対応は出題される。\n【混同注意】「次元の呪い」は変数（次元）が増えるほどデータが高次元空間に散らばり、距離計算や密度推定が困難になる現象であり、特徴量選択・次元削減の重要性の根拠となる。"
