    "explanation": "特徴量エンジニアリングとは、生データやドメイン知識をもとに機械学習モデルの予測性能向上に有用な変数（特徴量）を作成・変換・選択する一連の作業のことをいう。例として、「購買日」から「曜日」「月」「直近購買からの経過日数」等を新たな特徴量として生成すること、テキストをTF-IDFベクトルに変換すること等が含まれる。\n\nA：ハイパーパラメータの最適化はモデルチューニング（グリッドサーチ・ベイズ最適化等）の作業であり、特徴量エンジニアリングとは異なる工程。\nC：モデルのデプロイ・API公開はMLOps・システム開発の工程であり、特徴量エンジニアリングの定義ではない。\nD：センサー・APIの設計・開発はデータエンジニアリングの領域であり、特徴量エンジニアリングの説明として誤り。\n\n【頻出】特徴量エンジニアリングの具体例（日時分解・カテゴリのone-hotエンコーディング・テキストのベクトル化・ラグ特徴量）は出題される。\n【混同注意】特徴量選択（Feature Selection：既存変数から重要なものを選ぶ）と特徴量抽出（Feature Extraction：新たな特徴量を生成する）は特徴量エンジニアリングの2つのアプローチとして区別する。"
