    "answer": 3,
    "explanation": "不均衡データに対し多数クラスのサンプルを増やすことは問題の解決策にならず、むしろクラス間の不均衡をさらに悪化させる。正しい対処法は①オーバーサンプリング（少数クラスを増やす）②アンダーサンプリング（多数クラスを減らす）③SMOTE等の合成データ生成④コスト感応的学習（少数クラスの誤分類に大きなペナルティを課す）などである。\n\nA：正しい。オーバーサンプリングの手法には単純複製とSMOTE等の合成サンプル生成がある。\nB：正しい。SMOTE（Synthetic Minority Over-sampling Technique）は少数クラスのサンプル間をk近傍法で補間して合成サンプルを生成する手法。\nC：正しい。アンダーサンプリングはデータ量が減るためモデルが学習できる情報量が減るデメリットがあるが、実行コストが低い。\n\n【頻出】不均衡データの問題（正確度では評価できない理由）とSMOTE・オーバー/アンダーサンプリングの対処法は出題される。\n【混同注意】不均衡データでは精度（Accuracy）より適合率・再現率・F1スコア・AUC-ROCを評価指標として用いる点と一緒に覚える。"
