    "answer": 1,
    "explanation": "ブースティングとは、複数の「弱学習器」を順次学習させるアンサンブル手法のことをいう。前のモデルが誤分類したサンプルに高い重みを付けることで次のモデルがその誤りに集中して学習し、最終的にすべての弱学習器の出力を加重統合する。代表的手法としてAdaBoost・勾配ブースティング（XGBoost・LightGBM・CatBoost）がある。\n\nA：複数のモデルを並列に独立学習して多数決で統合する手法は「バギング」の説明であり、ブースティングの説明として誤り。\nC：計算コスト削減を目的とした手法の説明であり、ブースティングの定義とは異なる。ブースティングは順次学習のため計算コストは高い場合がある。\nD：データを無作為サブセットに分割して別モデルで学習する手法はバギング（特にランダムフォレスト）の説明であり、ブースティングではない。\n\n【頻出】バギング（並列・独立学習）とブースティング（逐次・誤り重点学習）の違いは最頻出。XGBoostが勾配ブースティングの代表実装であることも把握する。\n【混同注意】スタッキング（異なる種類のモデルの予測をメタモデルで統合する3層構造のアンサンブル）はバギング・ブースティングとは別のアンサンブル戦略として区別する。"
