    "explanation": "単語の分散表現（Word Embedding）とは、単語を意味的・文法的な類似性が距離に反映された低次元の実数値ベクトル（例：100〜300次元）として表現する手法のことをいう。Word2Vec・GloVe・fastText等が代表的な手法で、「王」−「男」＋「女」≈「女王」のような意味演算が可能。\n\nA：出現頻度に基づく整数値表現はカウントベースの表現（BoW：Bag of Words）の特性に近く、分散表現の定義として誤り。\nC：キーワードの有無を1か0で示すのはone-hotエンコーディングまたはBoWの説明であり、意味類似性を捉えない点で分散表現とは異なる。\nD：ASCIIコードへの変換は文字の数値エンコードであり、単語の意味表現とは全く異なる手法。\n\n【頻出】Word2Vecの概念（周辺語の文脈から単語の意味ベクトルを学習）とBERTなどのTransformerベース表現との関係は出題される。\n【混同注意】one-hotエンコーディング（スパース・高次元・意味なし）と分散表現（密・低次元・意味あり）の対比は重要。BERTやGPTは文脈依存の分散表現（文脈化表現）を生成する点でWord2Vecより進化している。"
