    "answer": 1,
    "explanation": "効果量（Effect Size）とは、コーエンのd・ピアソンのr・η²（イータ二乗）等の指標で表される「差や関連の実質的・実用的な大きさ」を示す指標のことをいう。統計的有意性（p値）はサンプルサイズの影響を大きく受けるが、効果量はサンプルサイズに依存しないため、結果の実用的な意味を評価するのに用いられる。\n\nA：効果量はp値や有意水準とは異なる独立した指標であり、「αと同義」は誤り。\nC：効果量が大きくても、サンプルサイズが小さければp値が有意水準を上回る（非有意）ことがある。効果量とp値は別の概念。\nD：効果量はサンプルサイズに依存しない指標として設計されている。サンプルサイズが増えるとp値は小さくなるが、効果量は変わらない（実際の差の大きさを反映）。\n\n【頻出】「統計的有意性（p値）」と「効果量（実用的な差の大きさ）」は別概念という点は試験頻出。大規模データでは小さな差でも有意になりやすいが、効果量が小さければ実用的意義が低い場合がある。\n【混同注意】コーエンのdの目安：d=0.2（小）・d=0.5（中）・d=0.8（大）として解釈する慣習がある。"
