    "answer": 1,
    "explanation": "CNN（Convolutional Neural Network）は、畳み込み層・プーリング層・全結合層から構成され、画像データの局所的な特徴（エッジ・テクスチャ・形状等）を階層的に抽出するのに特化したニューラルネットワークである。画像分類・物体検出・セグメンテーション等の画像認識タスクで高い性能を発揮する。\n\nA：売上予測・顧客離脱予測などの表形式構造化データには勾配ブースティング（XGBoost等）や多層パーセプトロン（MLP）がよく使われる。CNNが特段有利な領域ではない。\nC：時系列テキストデータの翻訳・文章生成にはRNN（Recurrent Neural Network）・LSTM・GRU・Transformerが主に使われる。\nD：強化学習の方策学習はQ学習・DQN・PPO等の強化学習アルゴリズムが担う領域であり、CNNはアタリゲームのDQNで状態入力（画像）に使われるが、それ自体は画像処理の役割。\n\n【頻出】CNN（画像）・RNN/LSTM（時系列・テキスト）・Transformer（テキスト・画像）という対応は試験の基本論点。\n【混同注意】近年はViT（Vision Transformer）により画像にもTransformerが使われるようになっており、CNNの優位性が絶対的でなくなりつつある点も理解しておく。"
