    "explanation": "MLOps（Machine Learning Operations）とは、DevOps（ソフトウェア開発と運用の統合）の考え方を機械学習に応用したもので、MLモデルの開発・実験管理・デプロイ・本番環境での監視・データドリフト検出・自動再学習といったライフサイクル全体を自動化・標準化・効率化する実践・プロセス・ツールの総称のことをいう。\n\nA：研究目的の実験管理・論文執筆支援ではなく、本番システムとしての継続的な運用を包含する点がMLOpsの特徴。実験管理（MLflow等）はMLOpsの一部。\nC：機械学習の数学的基礎の教育は「ML基礎教育」であり、MLOpsの説明として誤り。\nD：人間がラベリングする作業はデータアノテーションであり、MLOpsとは異なる。アノテーション結果はMLOpsパイプラインの入力データとなる場合がある。\n\n【頻出】MLOpsのコンポーネント（実験管理・CI/CD・モデルレジストリ・モデル監視・データパイプライン）は出題される。\n【混同注意】データドリフト（本番データの分布が学習時と乖離する現象）の検出・対応もMLOpsの重要な要素。モデルの定期的な再学習がなぜ必要かの文脈で問われる。"
