    "explanation": "プロンプトエンジニアリングとは、ChatGPTやClaudeなどの大規模言語モデルに対して、望ましい出力（回答・コード・要約・分類等）を引き出すために入力文（プロンプト）を設計・工夫する技術のことをいう。代表的な手法としてチェーン・オブ・ソート（思考ステップの明示）・フューショットプロンプティング（例示を含める）・ロールプロンプティング（役割指定）等がある。\n\nA：モデルパラメータを追加学習で更新する手法はファインチューニングであり、プロンプトエンジニアリングとは別の手法。プロンプトエンジニアリングはパラメータを変更せず入力のみを工夫する。\nC：前処理・クレンジングの自動化はデータエンジニアリングの領域であり、プロンプトエンジニアリングの定義とは異なる。\nD：LLM評価のベンチマーク設計・構築はモデル評価の作業であり、プロンプトエンジニアリングとは異なる概念。\n\n【頻出】プロンプトエンジニアリングとファインチューニング・RAGの違い（入力工夫 vs パラメータ更新 vs 外部知識検索）は出題される。\n【混同注意】ゼロショットプロンプティング（例なし）・フューショットプロンプティング（少数例あり）・チェーン・オブ・ソート（思考過程を示す）という手法の区別も押さえる。"
