    "explanation": "ヒートマップとは、行列形式のデータの各セルを色（濃淡・色相）で値の大小・相関の強弱を表現するグラフのことをいう。相関行列の可視化（変数間の相関係数をヒートマップで一覧表示）・地理的データの密度表示・ユーザー行動のクリックマップ等に適している。\n\nA：時間変化のトレンドを示すのは折れ線グラフが適している。ヒートマップで時系列を扱う場合もあるが（例：曜日×時間帯の件数ヒートマップ）、単純な時系列推移には不向き。\nB：カテゴリの構成比を示すのは円グラフ・積み上げ棒グラフが適しており、ヒートマップの主用途ではない。\nD：複数グループの分布を中央値・四分位数で比較するのは箱ひげ図が最適であり、ヒートマップの説明として誤り。\n\n【頻出】グラフ種類と用途の対応（ヒートマップ：相関行列・行列データ、バイオリンプロット：分布の形状比較、ワードクラウド：テキスト頻出語）は出題される。\n【混同注意】散布図行列（Pairplot）は変数ペアすべての散布図を並べたもの。ヒートマップはそれを色で表現した相関行列として使われることが多く、両者は補完的な可視化ツール。"
