    "explanation": "データパイプラインとは、データソース（センサー・DB・API等）からデータを収集し、変換・クレンジング・加工を経て、分析基盤（DWH・データレイク等）や下流システムに格納・配信するまでの一連の処理を自動化したフローのことをいう。Apache Airflow・AWS Glue・dbt等のツールで構築・管理されることが多い。\n\nB：ハイパーパラメータの自動探索はグリッドサーチ・ベイズ最適化等の手法であり、データパイプラインの定義とは異なる。\nC：ダッシュボードの複数ユーザーへの配信はBI・可視化ツールのサーバー機能であり、データパイプラインの説明として不正確。\nD：インデックス管理によるレコード並び替えはデータベースのパフォーマンス最適化の仕組みであり、データパイプラインとは異なる。\n\n【頻出】データパイプラインのツール（Apache Airflow・dbt・AWS Glue等）と、バッチ処理（定期実行）とストリーミング処理（リアルタイム）の違いは出題される。\n【混同注意】データパイプライン（データの流れ全体の自動化）とETL（特定の変換プロセス）は包含関係。ETLはデータパイプラインの構成要素の一つ。"
