"answer": 1,
"explanation": "集計表で複数グループの割合を比較する際は、各グループの絶対数（実数）が異なる場合でも公平に比較できるよう、構成比（割合・パーセント）を確認することが重要である。例えば男性100人中60人・女性20人中14人が賛成の場合、実数では60対14だが構成比では60%対70%であり、女性のほうが賛成割合が高い。\n\nA：行合計と列合計の割合が一致しているだけでは2変数間に独立性があるとは言えない。2変数間の独立性はカイ二乗検定で統計的に検証する必要がある。\nC：クロス集計表の行と列を入れ替えても（転置しても）各セルの度数は変わらない。ただし行・列の意味（周辺分布や条件付き分布の見え方）は変わる場合がある。\nD：合計が100%の集計表はさまざまなグラフ（積み上げ棒グラフ・横棒グラフ等）で表現できる。円グラフが唯一の選択肢ではなく、比較しにくい場合は棒グラフが推奨されることもある。\n\n【頻出】絶対数と構成比の使い分け（シンプソンのパラドックス等）は試験の重要論点。集計表の読み間違いはビジネスでの誤判断につながる典型例として出題される。\n【混同注意】シンプソンのパラドックスとは、集計データを層別に分けると全体の傾向と逆の結果が現れる現象。交絡変数が存在する典型例として覚える。"
