"explanation": "勾配降下法とは、機械学習モデルのパラメータ（重み）を最適化するアルゴリズムのことをいう。損失関数L(θ)のパラメータθに対する勾配（∂L/∂θ）を計算し、学習率αを掛けた分だけ勾配の逆方向にパラメータを更新する（θ ← θ − α × ∂L/∂θ）ことを繰り返して損失を最小化する。確率的勾配降下法（SGD）やAdamなどの派生手法が広く使われる。\n\nB：データを昇順に並べて上位サンプルを選択する処理は勾配降下法の説明として誤り。これは閾値処理やランキングに近い概念。\nC：ジニ不純度や情報利得による分岐条件の評価は決定木の学習アルゴリズムの説明であり、勾配降下法ではない。\nD：クラスター間距離の反復計算でデータを割り当てるのはk-meansクラスタリングのアルゴリズムの説明であり、勾配降下法とは異なる手法。\n\n【頻出】勾配降下法の更新式（θ ← θ − α × 勾配）と学習率（α）の役割は深層学習の基礎として出題される。学習率が大きすぎると発散、小さすぎると収束が遅い点も重要。\n【混同注意】バッチ勾配降下法（全データで勾配計算）・SGD（1サンプルずつ）・ミニバッチ勾配降下法（小さいバッチで計算）の3種類の違いと計算コスト・収束安定性のトレードオフを区別して覚える。"
