"answer": 1,
"explanation": "シャドウデプロイとは、新しいモデルを実際のユーザーへの影響なしに本番トラフィックに並行稼働（シャドウ）させ、その予測出力をログに記録して既存モデルの出力と比較・検証するデプロイ戦略のことをいう。本番環境のリアルデータでモデルの挙動を安全に確認できる利点がある。\n\nA：新旧モデルをユーザーに均等割り当てして比較するのはA/Bテストデプロイ（カナリアリリースの一形態）の説明であり、シャドウデプロイとは異なる。\nC：オフピーク時のみ稼働させる戦略はシャドウデプロイとは異なり、特定の時間制御を行う戦略。\nD：少量ユーザーに新モデルを提供して段階的に拡大するのはカナリアリリース（Canary Release）の説明であり、シャドウデプロイとは異なる。\n\n【頻出】MLOpsのデプロイ戦略（ブルーグリーンデプロイ・カナリアリリース・シャドウデプロイ・A/Bテスト）の各定義と使い分けは出題される。\n【混同注意】シャドウデプロイ（ユーザーへの影響ゼロで並行稼働）とカナリアリリース（一部ユーザーに新版を提供）は「リスク軽減」という共通目的を持ちながら手法が異なる。"
