"answer": 1,
"explanation": "フェデレーテッドラーニング（連合学習）とは、各クライアント（スマートフォン・病院・企業等）がローカルデータでモデルを学習し、生データは外部に送信せずに勾配更新量またはモデルパラメータのみを中央サーバーに送って集約（例：FedAvg：重み平均）することで、プライバシーを保護しながら共同でモデルを改善する分散学習手法のことをいう。\n\nA：生データを中央に集めて学習する従来の集中型学習の説明であり、データを共有せずに学習するフェデレーテッドラーニングとは逆のアプローチ。\nC：誤りを修正し合う順次学習はブースティングの説明であり、フェデレーテッドラーニングとは無関係な概念。\nD：大規模GPUクラスターでの分散並列学習は「分散深層学習（データ並列・モデル並列）」の説明であり、プライバシー保護を目的とするフェデレーテッドラーニングとは異なる。\n\n【頻出】フェデレーテッドラーニングのプライバシー保護（生データを共有しない）と差分プライバシー（ノイズ付加によるプライバシー保護）との組み合わせはAI倫理の文脈で出題される。\n【混同注意】フェデレーテッドラーニング（分散・プライバシー保護学習）と通常の分散学習（データを分割してGPU並列処理）はどちらも「分散」という言葉が含まれるが、目的と手法が全く異なる。"
