"因子分析は、観測データの分散を最大化する方向の主成分（合成変数）を算出するための手法のことをいう",
"因子分析は、目的変数を最もよく予測する説明変数の線形結合を求めるための手法のことをいう",
"因子分析は、データを事前定義されたカテゴリに分類するための教師あり学習手法のことをいう"
