"answer": 1,
"explanation": "仮説思考とは、問題解決や意思決定において「まず結論・解の方向性の仮説を設定し、その仮説を検証するために必要な分析・データ収集を行い、検証結果に応じて仮説を修正する」というアプローチのことをいう。全データを漫然と分析するのではなく、仮説を起点に効率的に分析を進める思考法として、コンサルティング・データ分析実務で重要視される。\n\nA：全件分析後に結論を出すアプローチは「帰納的アプローチ」に近い網羅的分析であり、仮説を先に立てる仮説思考とは対照的なスタイル。大規模データでは非効率になりがち。\nC：複数モデルの並列実行と自動選択はAutoMLの機能の一部であり、仮説思考の定義とは異なる。\nD：経験・勘を優先して都合よく解釈する行為は確証バイアスの一種であり、仮説思考（データで検証する客観的プロセス）とは反対のアプローチ。\n\n【頻出】仮説思考・ロジカルシンキング・MECE（漏れなくダブりなく）はDS検定のビジネス系論点として関連して出題される。\n【混同注意】仮説思考と確証バイアスは「先に考えを持つ」という点では似ているが、仮説思考は「データで反証する可能性を受け入れる」のに対し、確証バイアスは「反証データを無視する」という根本的な違いがある。"
