"explanation": "差分プライバシーとは、データセットに対するクエリや機械学習の学習プロセスにおいて、意図的に統計的ノイズ（ランダムな誤差）を加えることで、特定個人のデータがデータセットに存在しても存在しなくても分析結果がほぼ変わらないようにし、個人のプライバシーを数学的に保護する手法のことをいう。GoogleやApple等が実装に採用している。\n\nA：特定個人のレコードを削除する手法はデータ削除・匿名化処理であり、差分プライバシーの手法（ノイズ付加）とは異なる。\nC：2つのデータセットの変更差分を取る処理はデータパイプラインの増分処理（CDC：Change Data Capture）であり、プライバシー技術の差分プライバシーとは全く異なる。\nD：個人ごとに異なる暗号鍵を割り当てる手法は公開鍵暗号等の暗号化技術であり、差分プライバシーとは異なるプライバシー保護アプローチ。\n\n【頻出】差分プライバシーの基本概念（ノイズ付加・数学的プライバシー保証）とフェデレーテッドラーニングとの組み合わせはAI倫理・プライバシー保護の文脈で出題される。\n【混同注意】差分プライバシー（クエリへのノイズ付加）・k-匿名化（k人以上で同一属性を共有）・秘密計算（暗号化したまま計算）は異なるプライバシー保護技術として区別して覚える。"
