"explanation": "ロングテールとは、ECサイト等において人気上位の商品だけでなく、個々には販売数が少ないニッチな商品（分布の「裾」部分）を大量に取り揃えることで、それらの合計が少数のヒット商品の売上を上回りうるというビジネス・マーケティングの概念のことをいう。Amazonの「ロングテール戦略」が代表例。\n\nA：「上位20%が80%を生む」というのはパレートの法則（80:20の法則）の説明であり、ロングテールとは対照的な概念。ロングテールはこのパレートの原則が崩れうる現象を指す。\nC：正規分布の裾に外れ値が集まる現象は「裾の厚い分布（Fat Tail）」の説明であり、マーケティング・ビジネスのロングテールとは異なる文脈の概念。\nD：過去の影響が長期間持続する自己相関は「長期記憶（Long Memory）」や「持続性（Persistence）」の説明であり、ロングテールの定義とは異なる。\n\n【頻出】ロングテールとパレートの法則（80:20）の対比はビジネスデータ活用の文脈で出題される。デジタル経済・EC・ストリーミングサービスでのロングテール戦略の有効性も関連論点。\n【混同注意】確率分布の「裾の厚さ（Heavy Tail/Fat Tail）」という統計用語と、ビジネス概念の「ロングテール」は用語が似ているが文脈が異なる。試験での問われ方（ビジネス文脈か統計文脈か）を確認する。"
