"ハルシネーションとは、大規模言語モデルが事実に反する情報や存在しない情報を確信をもって生成する現象のことをいう",
"ハルシネーションとは、画像認識モデルが低品質な画像を入力した際に誤検出を起こす現象のことをいう",
