"answer": 1,
"explanation": "マルチモーダルAI（Multimodal AI）とは、テキスト・画像・音声・動画・センサーデータ等の複数の異なるデータ形式（モダリティ）を入力として受け取り、統合的に理解・処理・生成できるAIシステムのことをいう。GPT-4V（画像＋テキスト）・Gemini・Claude（画像理解）等が代表例。医療診断での画像＋電子カルテの統合分析、自動運転でのカメラ＋LiDAR融合等に活用される。\n\nA：複数モデルの並列実行・アンサンブルはアンサンブル学習の手法であり、マルチモーダルAIの定義（複数データ形式の統合処理）とは異なる。\nC：多言語翻訳専門のAIは多言語モデル（Multilingual Model）の説明であり、マルチモーダルAIは「言語の種類」ではなく「データ形式の種類」の多様性を扱う。\nD：複数データベースを横断する検索システムはマルチソース検索エンジンの説明であり、マルチモーダルAIとは異なる概念。\n\n【頻出】マルチモーダルAIの具体例（GPT-4V・Gemini・DALL-E：テキストから画像生成）とモダリティの組み合わせ（Text+Image・Audio+Text等）はLLMの発展として出題される。\n【混同注意】マルチモーダル（複数データ形式の統合）と多言語（Multiple Languages）は「マルチ」という共通語を含むが全く異なる概念。問題文の文脈（データ形式か言語か）を確認する。"
