"answer": 1,
"explanation": "量子コンピューティングとは、量子力学の原理（重ね合わせ：1つのqubitが0と1を同時に取る状態・量子もつれ：複数qubitの状態が相関する性質）を利用して、特定の計算問題（素因数分解・組み合わせ最適化・量子化学シミュレーション等）において古典コンピュータより指数関数的に高速な計算が期待される技術のことをいう。現時点ではNISQ（ノイズあり中規模量子）デバイスの段階であり、汎用的な実用化には至っていない。\n\nA：2026年時点でも量子コンピュータは特定の限定的な問題でのみ優位性が示されている段階であり、すべての機械学習タスクで古典コンピュータを凌駕しているわけではない。\nC：量子コンピューティングは量子機械学習（QML）・量子最適化・量子シミュレーション等への応用が活発に研究されており、「乱数生成専用・機械学習応用不可能」は誤り。\nD：現在の暗号化方式（RSA等）は量子コンピュータのShorのアルゴリズムによって解読リスクが高まるが、「即座にすべての暗号が解読される」は現時点の量子コンピュータの能力を大幅に誇張した記述。量子耐性暗号（PQC）の標準化が進められている。\n\n【頻出】量子コンピューティングの基本概念（qubit・重ね合わせ・量子もつれ）と、RSA暗号への脅威・量子耐性暗号（Post-Quantum Cryptography）はDS検定の最新技術論点として出題される。\n【混同注意】量子コンピュータ（量子力学を利用した特殊計算機）と量子通信（量子鍵配送：QKD）は異なる技術領域として区別する。"
