"answer": 1,
"explanation": "データメッシュとは、中央集権的なデータレイク・データウェアハウスの限界を克服するために提唱された分散型データアーキテクチャのことをいう。各ビジネスドメイン（営業・マーケ・製造等）がデータオーナーシップを持ち、データをプロダクトとして他ドメインに提供する。4原則は①ドメイン指向の分散データ所有②データをプロダクトとして扱う③セルフサービス型データ基盤④フェデレーテッドな計算ガバナンス。\n\nA：単一の中央集権型レイクへの集約はデータレイクアーキテクチャの説明であり、データメッシュはそれを分散化する考え方として対照的な位置づけにある。\nC：ネットワーク暗号化・分散保存はセキュリティ技術の説明であり、データメッシュのアーキテクチャ概念とは異なる。\nD：機械学習モデルの分散並列学習は「分散深層学習・フェデレーテッドラーニング」の領域であり、データメッシュの定義とは異なる。\n\n【頻出】データメッシュとデータレイク・データウェアハウスの比較（集中型 vs 分散型・ドメイン指向）はデータ基盤設計の論点として出題される。\n【混同注意】データメッシュ（分散所有・ドメイン指向）とデータファブリック（データの統合アクセスレイヤーを仮想化）はいずれも近年注目のアーキテクチャ概念だが、アプローチが異なる。"
