"ゼロショット学習とは、タスク固有の学習例を一切提供せずに、モデルが事前学習済みの知識だけで未知のタスクに対応する能力のことをいう",
"ゼロショット学習とは、射撃の訓練のように同一タスクをゼロ誤差になるまで繰り返し学習させる収束型学習のことをいう",
