"explanation": "仮名加工情報（個人情報保護法第2条第5項）とは、他の情報と照合しない限り特定の個人を識別できないよう加工した情報のことをいう。匿名加工情報と異なり、作成した事業者は他の情報と照合すれば復元が可能だが、その照合が禁止されている。主に社内での分析・AIの学習等の内部利用を目的とし、第三者への提供には原則として制限がかかる（一部例外あり）。\n\nB：仮名加工情報には匿名加工情報より緩やかな規制（利用目的の変更が容易・内部分析に利用可能）が課されており、「同等」は誤り。匿名加工情報のほうが規制が厳しく完全な復元不可が要件。\nC：仮名加工情報は照合によって復元が可能だが、作成者は照合が法令上禁止されている（個人情報保護法第41条第7項）。「照合禁止されていない」は誤り。\nD：仮名加工情報の作成にはQSA（準識別子）の処理（生年月日→年代への粗粒化・住所→都道府県のみ等）も含まれる場合があり、氏名のイニシャル化のみで要件を満たすとは限らない。\n\n【頻出】個人情報・仮名加工情報・匿名加工情報・統計情報の4類型の規制レベルの違い（強←個人情報＞仮名加工情報＞匿名加工情報＞統計情報→弱）はDS検定の法令論点として必須。\n【混同注意】仮名加工情報（照合可能だが照合禁止・内部利用向け）と匿名加工情報（復元不可・第三者提供可）の違いは2022年改正個人情報保護法で仮名加工情報が新設された際の重要ポイント。"
