"answer": 1,
"explanation": "データオーナーシップとは、データガバナンスの文脈において、特定のデータ資産に対して品質管理・定義・利用ルールの策定・アクセス権限の決定などの責任と権限を持つ主体（データオーナー：個人・部門・役職等）を明確にする概念のことをいう。データメッシュアーキテクチャでは各ドメインがデータオーナーシップを持つことが原則の一つ。\n\nA：物理サーバーの所有権・ハードウェア管理はIT資産管理の概念であり、データオーナーシップのデータガバナンス的意味とは異なる。\nC：データ分析の実施権限はデータアクセス権・分析権限の話であり、データオーナーシップ（責任と権限の主体の明確化）とは概念の粒度が異なる。\nD：個人情報保護法上のデータ主体の権利はGDPRの「データ主体の権利」に近い概念であり、組織内のデータガバナンスとしてのデータオーナーシップとは文脈が異なる。\n\n【頻出】データオーナー（ビジネス責任者）・データスチュワード（日常的なデータ管理担当者）・データカストディアン（技術的な保管担当者）の3役割の違いはデータガバナンスの組織論点として出題される。\n【混同注意】データオーナーシップ（組織内の責任主体の明確化）とデータ主権（国家・個人が自国・自己のデータをコントロールする権利）は類似する用語だが全く異なる文脈で使われる。"
