"explanation": "ファネル分析とは、ECサイト・アプリ・サービスにおけるユーザーの行動プロセス（例：サイト訪問→商品閲覧→カート追加→決済→購入完了）の各ステップでの通過率（コンバージョン率）と離脱率をじょうご（ファネル）状に可視化・分析する手法のことをいう。最も離脱率が高いボトルネックステップを特定して改善施策を立案するのに活用される。\n\nA：LTV予測のためのコホート別集計はコホート分析・LTV分析の説明であり、ファネル分析（行動プロセスの各ステップの通過率）とは目的・方法が異なる。\nC：季節変動・トレンド・残差を分解するのは時系列分解（STL分解等）の手法であり、ファネル分析の定義とは異なる。\nD：市場を複数セグメントに分割するのはマーケットセグメンテーションの手法であり、ファネル分析（単一サービス内のユーザー行動プロセスの分析）とは異なる。\n\n【頻出】ファネル分析のKPI（CVR：コンバージョン率・離脱率・ステップ別の通過人数）とボトルネック特定の活用例はGrowth HackingとA/Bテストとセットで出題される。\n【混同注意】マーケティングファネル（認知→興味→検討→購入→ロイヤルティという顧客獲得の概念的枠組み）とデータ分析のファネル分析（実際の行動ログを用いた定量的な通過率の分析）は関連するが異なるレベルの概念。"
