"answer": 1,
"explanation": "Dockerコンテナとは、アプリケーションのコード・ライブラリ・設定・依存関係を一つのDockerイメージにパッケージ化し、どのホスト環境でも同一の実行環境を再現できるOS仮想化技術のことをいう。データサイエンスでは分析コードの再現性確保・機械学習パイプラインの本番デプロイ・チーム間の環境共有に広く活用される。「自分のPCでは動くのに本番で動かない」問題を解決する。\n\nA：データの暗号化・アクセス権管理はセキュリティ技術であり、Dockerコンテナの説明として誤り。\nC：DockerコンテナはホストOSのカーネルを共有して動作する「OS仮想化」であり、物理サーバー全体をエミュレートする「VM（仮想マシン：フルシステム仮想化）」とは技術的仕組みが異なる。コンテナはVMよりも軽量で起動が速い。\nD：スケジューリングツール（Apache Airflow等）は定期実行の管理に使うツールであり、Dockerコンテナの定義とは異なる（Dockerはアプリの実行環境パッケージ）。\n\n【頻出】Docker（コンテナ）とKubernetes（コンテナオーケストレーション：複数コンテナの管理・スケーリング）の関係、およびMLOpsパイプラインへのコンテナ活用は出題される。\n【混同注意】コンテナ（軽量・OS共有・秒単位の起動）とVM仮想マシン（重量・独自OS・分単位の起動）の違いは技術的な仮想化の比較として区別して覚える。"
