"answer": 0,
"explanation": "スペクトル分析（スペクトル解析・周波数解析）とは、時系列データ（音声・脳波・経済データ等）をフーリエ変換等によって時間領域から周波数領域に変換し、データにどのような周期成分（例：月次・年次の周期）がどれだけの強度で含まれているかをパワースペクトルとして分析する手法のことをいう。信号処理・音声認識・季節性分析に活用される。\n\nB：可視光を観測して化学組成を分析するのは物理・化学の分光分析であり、統計的なスペクトル分析とは文脈が異なる（「スペクトル」という語を共有）。\nC：グラフのラプラシアン行列の固有値・固有ベクトルを使ってデータを分割する手法はスペクトラルクラスタリング（Spectral Clustering）の説明であり、時系列の周波数分析のスペクトル分析とは異なる（同じく「スペクトル」という語を共有するが別概念）。\nD：主成分分析は分散共分散行列の固有値分解を行う次元削減手法であり、スペクトル分析（時系列の周波数分解）の別名ではない。\n\n【頻出】フーリエ変換（連続信号の周波数分解）・FFT（高速フーリエ変換：離散信号の効率的な計算）・パワースペクトル密度（PSD：各周波数成分の強度）は信号処理とデータ分析の接点として出題される。\n【混同注意】スペクトル分析（時系列の周波数分解）とスペクトラルクラスタリング（グラフのラプラシアン固有値によるクラスタリング）は「スペクトル」という語を共有するが全く別の手法。"
