"answer": 1,
"explanation": "BI（Business Intelligence）ツールとは、企業のデータウェアハウス・データマート・データベース等に接続して、データの集計・可視化（グラフ・表・マップ等）・インタラクティブなダッシュボード作成・レポート配信を行い、ビジネスの現状把握・トレンド分析・意思決定支援を行うソフトウェアの総称のことをいう。代表例にTableau・Power BI・Looker・QlikViewがある。\n\nA：MLモデルの学習・デプロイ・監視のプラットフォームはMLOpsツール（MLflow・SageMaker等）の説明であり、BIツールの定義とは異なる。\nC：SQLを使ったDWHスキーマ設計・ETLパイプライン構築はデータエンジニアリングの作業（dbt・AWS Glue等）であり、BIツールの役割（可視化・レポーティング）とは異なる。\nD：自然言語処理でユーザーに自動応答するのはAIチャットボット・会話AIの説明であり、BIツールとは全く異なる。\n\n【頻出】BIツール（可視化・レポーティング）・DWH（データ蓄積）・ETLツール（データ変換・統合）・データカタログ（メタデータ管理）のデータ基盤スタックの役割分担はセットで出題される。\n【混同注意】セルフサービスBI（データ専門家でなくてもダッシュボードを作成できる機能）は近年のBIツールの重要な特性として覚える。Tableauの「Tableau Public」・MicrosoftのPower BIが代表的なセルフサービスBIツール。"
