"APIエコノミーとは、企業がAPIを通じてデータ・機能・サービスを外部と連携・提供することでビジネス価値を創出するエコシステムのことをいう",
"APIエコノミーとは、自社のデータをAPIで外部に公開することが法的に義務付けられているデータ共有規制の名称のことをいう",
