"answer": 1,
"explanation": "APIエコノミーとは、企業がAPI（Application Programming Interface）を通じてデータ・機能・サービスを外部のパートナー・開発者・他企業と連携・提供することで、新しいビジネスモデル・付加価値・収益源を創出するエコシステムのことをいう。Stripe（決済API）・Google Maps API・Open Banking（金融APIの開放）等がAPIエコノミーの代表例。データを「資産」として外部に提供することでネットワーク効果を生む。\n\nA：APIを独占管理して他社アクセスを防ぐことはAPIエコノミーの本質（オープン化・連携による価値創出）と逆の戦略。囲い込み戦略はAPIエコノミーとは異なる方向性。\nC：APIによるデータ公開を法的に義務化する規制は、EUのPSD2（決済データの開放義務）・オープンバンキング規制等の特定業界の規制に相当するものがあるが、「APIエコノミー」全体の定義ではない。\nD：API利用料金のダイナミックプライシングはAPIエコノミーの副次的な側面であり、エコシステム全体の定義としては不十分かつ限定的。\n\n【頻出】APIエコノミー・プラットフォームビジネス・ネットワーク効果・オープンイノベーションはデータ駆動ビジネスモデルの文脈でセット出題される。\n【混同注意】内部API（社内システム連携）・パートナーAPI（認定パートナー限定）・オープンAPI（一般公開）の3種類のAPIの公開範囲の違いも理解しておく。"
