"explanation": "データエンジニアリングとは、データの収集・蓄積・変換（ETL/ELT）・品質管理・データウェアハウス/データレイクの構築・パイプラインの開発と保守を担い、分析・機械学習に使えるデータ基盤を整備する役割のことをいう。データサイエンスはその基盤上でデータを統計解析・機械学習・可視化により分析し、ビジネス洞察・予測モデル・意思決定支援を提供する役割を担う。\n\nA：モデル構築・評価はデータサイエンスの業務、パイプライン構築・保守はデータエンジニアリングの業務であり、役割が逆になっている。\nC：データエンジニアリング（基盤構築・データの流れの管理）とデータサイエンス（分析・モデリング・洞察）は技術スタック・業務内容が異なる専門職域として区別される（ただし小規模組織では兼務する場合もある）。\nD：ビジネス戦略立案はビジネスアナリスト・経営企画の業務、ITインフラ管理はインフラエンジニアの業務であり、データエンジニアリングとデータサイエンスの説明として誤り。\n\n【頻出】データエンジニア（基盤構築・SQL・Spark・Airflow）・データサイエンティスト（分析・Python・機械学習・統計）・MLエンジニア（モデルのデプロイ・MLOps）の3役割の違いとスキルセットはセットで出題される。\n【混同注意】データアナリスト（BIツール・SQL・現状把握・レポート作成）とデータサイエンティスト（機械学習・統計・予測モデル構築）も役割が混同されやすいが、分析の深さ・活用する手法が異なる。"
