"answer": 0,
"explanation": "DVC（Data Version Control）とは、機械学習プロジェクトにおいてコードのGitと連携し、大容量の学習データ・前処理済みデータセット・モデルファイル・実験パイプラインのバージョンを管理するオープンソースツールおよび手法のことをいう。データファイル自体はS3・GCS等のストレージに保存し、DVCがメタデータ（.dvc ファイル）をGitで管理することで、コードとデータの状態を一緒に記録・再現できる。MLOpsの実験再現性確保に不可欠。\n\nB：DWHスキーマ変更の旧テーブルアーカイブはデータベースマイグレーション・スキーマバージョン管理（Flyway・Liquibase等）の説明であり、機械学習向けのDVCとは異なる。\nC：モデルのAPIバージョンのセマンティックバージョニングはMLflowのモデルレジストリ等の機能説明であり、データとパイプラインのバージョン管理ツールとしてのDVCの説明として不十分。\nD：ブロックチェーンによる不変記録データベースは分散台帳技術の説明であり、DVCの仕組み（Gitとの連携・ストレージメタデータ管理）とは全く異なる。\n\n【頻出】機械学習の再現性を確保するツールスタック（Git：コード管理、DVC：データ管理、MLflow：実験・モデル管理、Docker：環境管理）はMLOpsの基本コンポーネントとしてセット出題される。\n【混同注意】DVCはデータの「差分のみ」を効率的に保存するため、大容量データセットのバージョン管理をGitのみで行う（Gitには大ファイルは不向き）問題を解決する補完ツールとして位置づけられる。"
