"answer": 0,
"explanation": "主成分分析（PCA）では、データの分散共分散行列（または相関行列）を固有値分解することで、各固有値λᵢが対応する主成分が説明する分散量（情報量）を表し、対応する固有ベクトルuᵢが主成分の方向（元の変数空間での主成分の向き：主成分負荷量）を表す。固有値が大きいほど多くの分散を説明し、累積寄与率で選択する主成分数を決定する。\n\nB：固有値は変数間の相関係数に対応するものではなく、各主成分が捉える分散量に対応する。固有ベクトルは欠損値補完とは無関係であり主成分の向きを示す。\nC：固有値が最大の第1主成分が最も分散を説明する最重要な主成分であり、最小固有値の主成分は最も情報量が少ない。「最小値が最重要」は逆の記述。\nD：分散共分散行列はエルミート対称行列（半正定値行列）であるため固有値分解は常に存在し収束が保証される。実務でもNumPy・scikit-learnでの固有値分解が標準的に使われる。\n\n【頻出】PCAの固有値（寄与率：各主成分が全分散に占める割合＝λᵢ÷Σλᵢ）・累積寄与率（主成分数の選択基準：一般に80〜90%以上）・スクリープロット（固有値の減少曲線）はセットで出題される。\n【混同注意】分散共分散行列でのPCA（スケール依存）と相関行列でのPCA（各変数を標準化してスケール非依存）の使い分け（単位が異なる変数が混在する場合は相関行列を使用）も理解しておく。"
