"explanation": "AIアライメント問題（AI Alignment Problem）とは、高度なAIシステムが人間の意図・倫理的価値観・社会的目標と一致（アライメント）した方法で行動するよう設計・訓練することの技術的・哲学的困難さに関する課題のことをいう。報酬ハッキング（意図しない方法で目標を達成する）・分配シフト・仕様のズレ（Specification Gaming）等が具体的な問題例。RLHF・Constitutional AI・解釈可能なAI等がアライメント研究の取り組みとして知られる。\n\nA：カラム名・データ型のマッピングはデータ統合・ETLのスキーマアライメント作業であり、AI安全性の研究領域としてのアライメント問題とは文脈が異なる。\nC：学習データとテストデータの分布の不一致による性能低下はデータドリフト・共変量シフトの問題であり、AIアライメント（人間の価値観との一致）の課題とは異なる。\nD：レイヤーの活性化分布の正規化はバッチ正規化の説明であり、AIアライメント問題とは無関係。\n\n【頻出】AIアライメント問題・AI安全性（AI Safety）・RLHF（人間フィードバックによる価値観の組み込み）・Constitutional AI（Anthropicの手法）は責任あるAI開発の文脈でDS検定の最新論点として出題される。\n【混同注意】AIアライメント（価値観の一致）とAI説明可能性（XAI：判断の透明化）は関連するが異なる課題。アライメントは「何をするか」の目標設定の問題、XAIは「なぜそうしたか」の説明の問題として区別する。"
