"SEMは観測変数間の因果関係を表す構造方程式と、潜在変数を含む測定モデルを同時に推定でき、パス解析・確認的因子分析を包含する多変量解析手法のことをいう",
"SEMは時系列データのARIMAモデルとベクトル自己回帰モデル（VAR）を組み合わせた多変量時系列分析の別名のことをいう",
