"explanation": "データ融合（Data Fusion）とは、複数のセンサー（カメラ・LiDAR・GPS等）・データソース（テキスト・画像・構造化データ等）からの情報を統合することで、単一ソースより精度の高い状況認識・情報抽出を行うことをいう（例：自動運転のマルチセンサー融合）。モデルアンサンブルとは、複数の機械学習モデルの予測結果を多数決・平均・スタッキング等で統合して予測精度を高める手法をいう。前者はデータレベル、後者はモデルレベルの統合として区別される。\n\nB：データ融合（データ入力レベルの統合）とモデルアンサンブル（モデル出力レベルの統合）は異なる概念・目的・実装をもち、同一ではない。\nC：データ融合もモデルアンサンブルも一般的に精度向上に貢献する手法として広く実践されており、「精度を低下させるリスクがあり推奨されない」は誤り。ただし実装を誤ると精度改善しない場合もある。\nD：データ融合は自動運転・医療診断・気象予測等の多様な応用があり時系列専用ではなく、モデルアンサンブルも画像専用ではなく表形式・テキスト・あらゆるデータに適用できる。\n\n【頻出】マルチモーダルAI（異なるモダリティのデータ融合）とアンサンブル学習（複数モデルの予測統合）の違い、センサーフュージョン（自動運転・ロボティクス）への応用はDS検定の実応用論点として出題される。\n【混同注意】フィーチャーフュージョン（特徴量レベルでの統合：中間層の結合）とデシジョンフュージョン（出力/予測レベルでの統合：アンサンブルに近い）はデータ融合の2つのレベルとして区別して覚える。"
