"explanation": "インダストリー4.0（第4次産業革命）とは、蒸気機関（第1次）・電力と大量生産（第2次）・電子工学とITによる自動化（第3次）に続く、IoT・AI・ビッグデータ・デジタルツイン・サイバー物理システム（CPS）・クラウド・ロボティクス等の融合によって製造業の生産プロセスをスマート化・自律化・個別化する産業変革のことをいう。2011年にドイツが提唱し、現在は世界的な概念として普及している。\n\nA：CRMシステムの調達指針という説明はインダストリー4.0の定義として完全に誤り。CRMは顧客関係管理のシステムであり、製造業のスマート化の概念とは無関係。\nC：インダストリー4.0の核心はデータ収集・AI分析・デジタルツインによる意思決定支援であり、データ分析・AIとの関係は非常に深い。「物理的自動化のみ・AIと無関係」は誤り。\nD：インダストリー4.0はドイツ発祥の概念だが「スマート工場・スマートマニュファクチャリング」として日本・中国・米国を含む世界各国の製造業DXの指針となっている。「ドイツのみ」は誤り。\n\n【頻出】インダストリー4.0の構成技術（IoT・AI・デジタルツイン・CPS・5G・ロボティクス）と日本の「Society 5.0」との関連はDS検定の社会・産業応用論点として出題される。\n【混同注意】インダストリー4.0（製造業のスマート化）とDX（企業全体のデジタル変革）は重なる部分があるが、インダストリー4.0は製造・生産プロセスに特化した概念として区別して理解する。"
