"データの民主化とは特定の経済圏でデータを民主的に管理する政治的な概念であり、企業のデータ戦略とは無関係である",
"データの民主化が進むとデータ専門家の仕事がなくなるため、データの民主化への取り組みはデータ組織の解体を意味する",
"データの民主化には専門的な統計知識が必須であり、非専門家が分析ツールを使ってデータにアクセスすることは推奨されない"
