"answer": 0,
"explanation": "データの民主化（Data Democratization）とはデータサイエンティスト等の専門家だけでなく、ビジネス現場の担当者・経営者を含む幅広い人がデータにアクセスし活用できる状態を目指す取り組みのことをいう。推進に伴う課題として①アクセス拡大に伴う情報漏洩・プライバシーリスクの増大→適切なアクセス制御②リテラシーのない人による誤った分析・意思決定→教育の充実③データガバナンスの複雑化等がある。セルフサービスBIツールがこれを支援する。\n\nB：データの民主化は企業・組織内でのデータ活用の民主化（アクセス権限の拡大と組織能力の向上）を指す概念であり、政治的・経済圏の概念とは無関係。\nC：データの民主化はデータ専門家の仕事を「排除」するのではなく、より高度な分析・モデリング・インフラ設計等の専門的領域に集中できるよう役割を進化させる方向に働く。「組織の解体」は誤り。\nD：データの民主化の目的は専門知識なしでもデータ活用できる環境（セルフサービスBI・ノーコード分析ツール等）の整備であり、「非専門家の利用は推奨されない」は民主化の趣旨と逆。\n\n【頻出】データ民主化の推進手段（セルフサービスBI・データカタログ・データリテラシー教育・RBACによる適切な権限管理）はデータガバナンスとセットで出題される。\n【混同注意】データの民主化（広くアクセス・活用できる状態）とオープンデータ（政府・公的機関が一般公開するデータ）は「データを広く開放する」という方向性は共通するが、対象（組織内 vs 社会全体）が異なる。"
