"answer": 1,
"explanation": "AIガバナンスフレームワークとは、AI技術の開発・導入・運用全体にわたって、責任の所在の明確化・透明性の確保・公平性の担保・安全性の維持・プライバシー保護・説明責任の実現・リスク管理等を達成するための方針・プロセス・技術的手段・組織体制を包括的に定めた枠組みのことをいう。代表例としてNISTのAI RMF（AI Risk Management Framework）・EU AI Act・ISO/IEC 42001等がある。\n\nA：AIの計算速度最大化はハードウェア最適化・アクセラレーター設計の領域であり、AIガバナンス（責任・透明性・安全性の確保）とは全く異なる概念。\nC：AI生成コンテンツの著作権保護は法的な知的財産権の議論であり、AIガバナンスフレームワーク全体の定義としては非常に狭い一側面にすぎない。\nD：論文の引用形式の学術標準はスタイルガイド（APA・IEEE等）の話であり、AIガバナンスフレームワークの定義とは無関係。\n\n【頻出】EU AI Actの高リスクAIの定義・NIST AI RMFの4機能（Govern・Map・Measure・Manage）・ISO/IEC 42001（AIマネジメントシステム）はAIガバナンスの国際標準として出題頻度が高まっている。\n【混同注意】AIガバナンス（組織的な管理体制・方針）とAI倫理（価値観・規範の議論）は補完的な概念。ガバナンスは「どう管理するか」の仕組み、倫理は「何が正しいか」の規範として区別する。"
