"explanation": "感度分析（Sensitivity Analysis）とは、1つまたは少数の入力変数を一定範囲で変化させたとき、出力値がどの程度変動するかを定量化して「どの変数が最も影響力が高いか」を特定する手法のことをいう。シナリオ分析（Scenario Analysis）とは、複数の変数を同時に変化させた具体的な状況（楽観シナリオ・基本シナリオ・悲観シナリオ等）を定義して、それぞれでの結果を評価・比較する手法のことをいう。\n\nB：感度分析も将来の不確実性に対する分析ツールであり、「感度分析は将来不確実性・シナリオ分析は過去外れ値」という区分は誤り。両者ともに将来予測・リスク評価に使われる。\nC：両者は入力変数の変化を扱う点では類似するが、変化させる変数の数・シナリオの定義の仕方・目的（感度の特定 vs シナリオ別の結果評価）が異なる別手法として区別される。\nD：感度分析もシナリオ分析も機械学習・財務・工学・政策分析等の広範な分野に適用できる汎用的な分析手法であり、特定分野専用ではない。\n\n【頻出】感度分析（重要変数の特定）・シナリオ分析（複数の将来シナリオの評価）・モンテカルロシミュレーション（確率的なシナリオの大量生成）は不確実性分析の3大手法としてセットで出題される。\n【混同注意】XAIのSHAP（モデル内での各特徴量の貢献度）と感度分析（入力の変化に対する出力の変化率）は似た目的（重要変数の特定）をもつが、機械学習モデルの解釈か意思決定モデルの分析かという文脈が異なる。"
