"answer": 1,
"explanation": "最尤推定量（MLE：Maximum Likelihood Estimator）の漸近的性質として、標本サイズnが大きくなるにつれて①漸近不偏性（バイアス→0）②一致性（真の値に確率収束）③漸近有効性（クラメール・ラオ下限を漸近的に達成）④漸近正規性（√n(θ̂MLE−θ)は正規分布に収束）という4つの望ましい性質を一般的にもつことが知られている。\n\nA：MLEは有限標本では一般に偏りがある（バイアスが生じる）場合がある（例：正規分布の分散のMLE（÷n）は偏りあり、不偏推定量は÷(n-1)）。「必ず不偏」は誤り。\nC：多くの確率モデルでMLEは閉形式解をもたず（例：混合ガウスモデル・ロジスティック回帰等）、EMアルゴリズムや勾配降下法等の数値的最適化が必要。\nD：MLEは事前分布を使用しない頻度主義的手法であり、ベイズ推定（事後分布の活用）とは異なる。MAP推定は事前分布が無情報（一様）の場合にMLEと一致するが、一般には異なる値を返す。\n\n【頻出】MLEの漸近的性質（不偏性・一致性・有効性・正規性）とフィッシャー情報量・クラメール・ラオの下限の関係は統計推定理論の重要論点として出題される。\n【混同注意】MLE（事前分布なし・尤度最大化）・MAP推定（事前分布あり・事後分布の最頻値）・ベイズ推定（事後分布全体を求める）の3者の関係を正確に区別して覚える。"
