"explanation": "CDO（Chief Data Officer：最高データ責任者）とは、組織全体にわたってデータを戦略的な経営資産として位置づけ、①データ戦略の立案・推進②データガバナンス（品質・セキュリティ・プライバシー）の統括③データドリブン文化の醸成④データ分析・AIによるビジネス価値創出の加速⑤CTO（技術）・CDO（データ）・CFO（財務）等との連携を担う経営幹部の役職のことをいう。\n\nA：クラウドインフラの物理的な運用はインフラエンジニアリング部門・CTOの管轄であり、CDOの主たる役割（データ戦略・ガバナンス・価値創出）とは異なる。\nC：データサイエンティスト（個別プロジェクトの分析担当者）は個人貢献者であり、組織全体のデータ戦略を担う経営レベルの役職であるCDOとは役職の位置づけが根本的に異なる。\nD：GDPR対応のDPO（Data Protection Officer：データ保護責任者）とCDO（最高データ責任者）は混同されやすいが、DPOはプライバシー・コンプライアンス専門の役割であり、CDOはデータ活用・価値創出まで含む広い責任をもつ。\n\n【頻出】CDO・CTO・CDAO（最高データ・分析責任者）・DPO（データ保護責任者）の役割の違いとデータガバナンス組織の構成はDS検定のマネジメント論点として出題される。\n【混同注意】CDO（Chief Data Officer：最高データ責任者）とCDO（Chief Digital Officer：最高デジタル責任者）は同一の略称が2つの異なる役職に使われる場合がある。文脈によって判断する。"
