"過分散とは、標本サイズが過剰に大きいために統計的有意性が過度に検出されやすくなるサンプルサイズ問題のことをいう",
"過分散とは、主成分分析において第1主成分が全分散の過剰な割合を説明することで他の主成分が無意味になる問題のことをいう"
