"サンプリング定理とは、連続信号をデジタル化する際に、信号に含まれる最高周波数の2倍以上のサンプリング周波数で標本化すれば元の信号を完全に再現できるという定理のことをいう",
"サンプリング定理とは、確率的サンプリングにおいて無限の母集団から有限の標本を取る場合に推定誤差がゼロに収束するという大数の法則の別名のことをいう",
"サンプリング定理とは、機械学習のミニバッチ学習において、バッチサイズを最低限の標本数以上に設定することで学習が安定化するという経験則のことをいう"
