"人間評価とは、AIシステムの出力品質を人間の評価者が直接判断する方法であり、自動指標では捉えにくい有用性・一貫性・倫理的適切さ等の側面を評価できる一方でコスト・スケーラビリティの課題がある",
"人間評価は主観的なバイアスが常に混入するため、科学的な評価方法としては不適切であり研究・実務では使用すべきでない",
