"answer": 1,
"explanation": "Apache Sparkとは、大規模データの分散処理のためのオープンソースフレームワークのことをいう。主な特徴は①メモリ内処理（In-Memory Computing）によりHadoop MapReduceより最大100倍高速②バッチ処理（Spark Core）・SQLクエリ（Spark SQL）・ストリーミング（Spark Streaming/Structured Streaming）・機械学習（MLlib）・グラフ処理（GraphX）を統一APIで提供③Scala・Python（PySpark）・Java・R等の多言語サポート。\n\nA：SparkはHadoopクラスタ・Kubernetes・スタンドアロンモードで分散クラスター上で動作するフレームワークであり、「単一サーバーのみ・分散対応なし」は誤り（単一ノードモードも存在するが限定的）。\nC：SparkはMLlib（機械学習）だけでなくデータ前処理・分析・SQLクエリ等の幅広いデータ処理に使用される汎用フレームワークであり、「サービングのみ特化」は誤り。\nD：SparkはAWS S3・Azure Blob Storage・Google Cloud Storage等のクラウドストレージに接続可能であり、「HDFS必須」は誤り。多くのクラウドのマネージドSpark（Databricks・EMR・Dataproc）ではHDFS不使用が一般的。\n\n【頻出】Spark（大規模バッチ・ML）・Kafka（メッセージキュー・ストリーミング）・Flink（低遅延ストリーミング）・Airflow（ワークフロースケジューリング）の役割分担はビッグデータ基盤の構成として出題される。\n【混同注意】Hadoop MapReduce（ディスクベースの2ステップ処理：遅い）とSpark（インメモリ処理：高速）の違いと、HadoopのHDFSはストレージ、MapReduceは処理エンジンという役割の分離を理解する。"
